-- Synthetic profiles only; all changes roll back. Run on the planning stack.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id) VALUES ('aaaaaaaa-0000-4000-8000-000000000001'),('bbbbbbbb-0000-4000-8000-000000000002'),('cccccccc-0000-4000-8000-000000000003');
INSERT INTO public.profiles(id,display_name) VALUES ('aaaaaaaa-0000-4000-8000-000000000001','Organizer fixture'),('bbbbbbbb-0000-4000-8000-000000000002','Member fixture'),('cccccccc-0000-4000-8000-000000000003','Other fixture');
INSERT INTO rdd_private.planning_organizers(user_id) VALUES ('aaaaaaaa-0000-4000-8000-000000000001');
CREATE FUNCTION pg_temp.write(action text,payload jsonb,op uuid DEFAULT gen_random_uuid()) RETURNS jsonb LANGUAGE sql AS $$
 SELECT public.rdd_planning_write(op,action,payload||jsonb_build_object('actor_id',auth.uid()));
$$;
CREATE FUNCTION pg_temp.poll() RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('poll_id','11111111-0000-4000-8000-000000000001','revision',0,'title','Synthetic planning','scope','both','closes_local','2090-10-01T20:00','publish',true,'options',jsonb_build_array(jsonb_build_object('kind','date','starts_local','2090-10-09T19:00'),jsonb_build_object('kind','venue','venue','Local hall')));
$$;
CREATE FUNCTION pg_temp.my_poll() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_path_query_first(public.rdd_planning_read(),'$.polls[*] ? (@.id == "11111111-0000-4000-8000-000000000001")') $$;
CREATE FUNCTION pg_temp.night_id() RETURNS text LANGUAGE sql AS $$ SELECT jsonb_path_query_first(public.rdd_planning_read(),'$.nights[*] ? (@.title == "Synthetic night")')->>'night_id' $$;
SELECT ok(NOT has_table_privilege('authenticated','rdd_private.planning_organizers','INSERT'),'Cannot self-promote');
SELECT ok(NOT has_schema_privilege('authenticated','rdd_private','USAGE'),'Private records are not exposed');
SELECT ok(NOT has_table_privilege('authenticated','rdd_private.planning_votes','SELECT'),'Cannot read other ballots directly');
SELECT ok(NOT has_table_privilege('authenticated','rdd_private.planning_rsvps','UPDATE'),'Cannot bypass RSVP RPC');
SELECT ok(to_regclass('public.seasons') IS NULL,'Legacy-only baseline');
SELECT throws_ok($$SELECT rdd_private.planning_time('2027-03-14T02:30')$$,'22023',null,'Rejects DST gap');
SELECT throws_ok($$SELECT rdd_private.planning_time('2027-11-07T01:30')$$,'22023',null,'Rejects ambiguous DST hour');
SELECT is(rdd_private.planning_time('2027-07-01T19:00'),'2027-07-01T23:00Z'::timestamptz,'Uses Rochester time');
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claims','{"role":"anon"}',true);
SELECT throws_ok($$SELECT public.rdd_planning_read()$$,'42501',null,'Signed-out planning read denied');
SELECT throws_ok($$SELECT public.rdd_planning_night_status('{}'::uuid[])$$,'42501',null,'Signed-out night statuses denied');
SELECT throws_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll())$$,'42501',null,'Signed-out write denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT is(public.rdd_planning_read()->>'organizer','false','Member has no organizer grant');
SELECT throws_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll())$$,'42501',null,'Member cannot create poll');
SELECT throws_ok($$SELECT public.rdd_planning_write(gen_random_uuid(),'vote','{"actor_id":"aaaaaaaa-0000-4000-8000-000000000001"}')$$,'42501',null,'Actor spoof rejected');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-4000-8000-000000000001"}',true);
SELECT is(public.rdd_planning_read()->>'organizer','true','Trusted grant recognized');
SELECT lives_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll(),'99999999-0000-4000-8000-000000000001')$$,'Organizer publishes both-category poll');
SELECT is(pg_temp.write('save_poll',pg_temp.poll(),'99999999-0000-4000-8000-000000000001')->>'replayed','true','Publish retry idempotent');
SELECT throws_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll()||'{"title":"changed"}','99999999-0000-4000-8000-000000000001')$$,'PT409',null,'Changed payload cannot reuse operation');
SELECT throws_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll()||'{"revision":1}')$$,'40001',null,'Published question immutable');
SELECT lives_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll()||'{"poll_id":"11111111-0000-4000-8000-000000000002","publish":false}')$$,'Can save draft');
SELECT lives_ok($$SELECT pg_temp.write('save_poll',pg_temp.poll()||'{"poll_id":"11111111-0000-4000-8000-000000000003","closes_local":null}')$$,'Manual-only poll');
SELECT throws_ok($$SELECT pg_temp.write('schedule','{"poll_id":"11111111-0000-4000-8000-000000000003","title":"Do not schedule"}')$$,'22023',null,'Manual-only poll must close before scheduling');
SELECT lives_ok($$SELECT pg_temp.write('cancel_poll','{"poll_id":"11111111-0000-4000-8000-000000000003","revision":1}')$$,'Organizer cancels poll');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT is((public.rdd_planning_read()->>'poll_total')::integer,2,'Draft invisible to member');
SELECT throws_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"venue"}')$$,'23514',null,'Missing venue cannot become an empty option');
SELECT lives_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"venue","venue":"Other hall"}')$$,'Member suggests venue');
SELECT throws_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"venue","venue":"  OTHER  hall  "}')$$,'23505',null,'Normalized duplicate rejected');
SELECT is((pg_temp.my_poll()->>'suggestions_used')::integer,1,'Duplicate does not consume allowance');
SELECT lives_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"date","starts_local":"2090-10-10T19:00"}')$$,'Second suggestion across category');
SELECT throws_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"venue","venue":"Third hall"}')$$,'PT422',null,'Two total across categories');
SELECT lives_ok($$SELECT pg_temp.write('vote',jsonb_build_object('poll_id','11111111-0000-4000-8000-000000000001','revision',0,'options',jsonb_path_query_array(pg_temp.my_poll(),'$.options[*].id'))),'first ballot accepts all options'$$,'First ballot accepts all options');
SELECT is(jsonb_array_length(pg_temp.my_poll()->'mine'),4,'Multiple choices stored');
SELECT throws_ok($$SELECT pg_temp.write('vote','{"poll_id":"11111111-0000-4000-8000-000000000001","revision":0,"options":[]}')$$,'40001',null,'Stale ballot rejected');
SELECT lives_ok($$SELECT pg_temp.write('vote','{"poll_id":"11111111-0000-4000-8000-000000000001","revision":1,"options":[]}', '99999999-0000-4000-8000-000000000002')$$,'Can clear ballot');
SELECT is(jsonb_array_length(pg_temp.my_poll()->'mine'),0,'Clear does not mean Not going');
SELECT lives_ok($$SELECT pg_temp.write('withdraw',jsonb_build_object('poll_id','11111111-0000-4000-8000-000000000001','option_id',jsonb_path_query_first(pg_temp.my_poll(),'$.options[*] ? (@.venue == "Other hall")')->>'id'))$$,'Member withdraws own suggestion');
SELECT is((pg_temp.my_poll()->>'suggestions_used')::integer,2,'Withdrawal retains consumed slot');
SELECT throws_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"venue","venue":"Third hall"}')$$,'PT422',null,'Withdrawal cannot bypass cap');
SELECT is(pg_temp.my_poll()->'pairs','[]'::jsonb,'Member does not receive overlap data');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-4000-8000-000000000001"}',true);
SELECT lives_ok($$SELECT pg_temp.write('close_poll','{"poll_id":"11111111-0000-4000-8000-000000000001","revision":1}')$$,'Manual close');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT throws_ok($$SELECT pg_temp.write('vote','{"poll_id":"11111111-0000-4000-8000-000000000001","revision":2,"options":[]}')$$,'PT410',null,'Closed votes rejected');
SELECT is(pg_temp.write('vote','{"poll_id":"11111111-0000-4000-8000-000000000001","revision":1,"options":[]}', '99999999-0000-4000-8000-000000000002')->>'replayed','true','Committed retry works after deadline');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-4000-8000-000000000001"}',true);
SELECT lives_ok($$SELECT pg_temp.write('schedule',jsonb_build_object('poll_id','11111111-0000-4000-8000-000000000001','title','Synthetic night','date_option',jsonb_path_query_first(pg_temp.my_poll(),'$.options[*] ? (@.kind == "date")')->>'id','venue_option',jsonb_path_query_first(pg_temp.my_poll(),'$.options[*] ? (@.venue == "Local hall")')->>'id'),'99999999-0000-4000-8000-000000000003')$$,'Schedule from closed poll');
SELECT is(pg_temp.my_poll()->>'status','scheduled','Poll is linked to night');
SELECT is((SELECT count(*)::integer FROM public.league_night_attendees),0,'Scheduling does not mark anyone present');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT lives_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',1,'revision',0,'going',true))$$,'Member RSVPs Going');
SELECT throws_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',1,'revision',0,'going',false))$$,'40001',null,'Stale RSVP rejected');
SELECT lives_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',1,'revision',1,'going',false))$$,'Change response to Not going');
SELECT throws_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',1,'revision',2,'going','maybe'))$$,'22023',null,'No Maybe value');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-4000-8000-000000000001"}',true);
SELECT lives_ok($$SELECT pg_temp.write('edit_night',jsonb_build_object('night_id',pg_temp.night_id(),'revision',1,'title','Synthetic night','starts_local','2090-10-12T19:00','venue','Changed hall'))$$,'Reschedule night');
SELECT is(jsonb_array_length(jsonb_path_query_first(public.rdd_planning_read(),'$.nights[*] ? (@.title == "Synthetic night")')->'responses'),0,'Old RSVP excluded after reschedule');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT throws_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',1,'revision',2,'going',true))$$,'40001',null,'Old event revision cannot confirm changed event');
SELECT lives_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',2,'revision',2,'going',true))$$,'Explicit reconfirmation accepted');
RESET ROLE;
UPDATE rdd_private.planning_schedules SET rsvp_closes_at=date_trunc('minute',now())-interval '1 minute';
UPDATE rdd_private.planning_polls SET status='open',closes_at=now()-interval '1 second' WHERE id='11111111-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT is(pg_temp.my_poll()->>'status','closed','Deadline closure without a scheduler');
SELECT throws_ok($$SELECT pg_temp.write('vote','{"poll_id":"11111111-0000-4000-8000-000000000001","revision":2,"options":[]}')$$,'PT410',null,'Server rejects late ballot');
SELECT throws_ok($$SELECT pg_temp.write('suggest','{"poll_id":"11111111-0000-4000-8000-000000000001","kind":"venue","venue":"Late hall"}')$$,'PT410',null,'Server rejects late suggestion');
SELECT throws_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',2,'revision',3,'going',false))$$,'PT410',null,'Server rejects late RSVP');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"aaaaaaaa-0000-4000-8000-000000000001"}',true);
CREATE FUNCTION pg_temp.edit_closed_night() RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('night_id',pg_temp.night_id(),'revision',2,'title','Synthetic night','starts_local','2090-10-12T19:00','venue','Changed hall','notes','Corrected notes','rsvp_closes_local',to_char((date_trunc('minute',now())-interval '1 minute') AT TIME ZONE 'America/New_York','YYYY-MM-DD"T"HH24:MI'));
$$;
SELECT lives_ok($$SELECT pg_temp.write('edit_night',pg_temp.edit_closed_night())$$,'Edit notes while retaining elapsed RSVP cutoff');
SELECT is(jsonb_path_query_first(public.rdd_planning_read(),'$.nights[*] ? (@.title == "Synthetic night")')->>'notes','Corrected notes','Correction saved after RSVP cutoff');
SELECT is(jsonb_path_query_first(public.rdd_planning_read(),'$.nights[*] ? (@.title == "Synthetic night")')->>'event_revision','2','Notes correction preserves responses');
SELECT throws_ok($$SELECT pg_temp.write('rsvp',jsonb_build_object('night_id',pg_temp.night_id(),'event_revision',2,'revision',0,'going',true))$$,'PT410',null,'Correction does not reopen RSVPs');
SELECT throws_ok($$SELECT pg_temp.write('edit_night',pg_temp.edit_closed_night()||jsonb_build_object('revision',3,'rsvp_closes_local','2020-01-01T19:00'))$$,'22023',null,'Cannot change cutoff to a different past time');
SELECT is(public.rdd_planning_night_status(ARRAY[pg_temp.night_id()::uuid])->>pg_temp.night_id(),'scheduled','Scheduled state available to lobby');
SELECT lives_ok($$SELECT pg_temp.write('cancel_night',jsonb_build_object('night_id',pg_temp.night_id(),'revision',3))$$,'Cancel corrected night');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"bbbbbbbb-0000-4000-8000-000000000002"}',true);
SELECT is(public.rdd_planning_night_status(ARRAY[pg_temp.night_id()::uuid])->>pg_temp.night_id(),'cancelled','Member sees cancellation through status RPC');
SELECT is(public.rdd_planning_night_status(ARRAY['99999999-0000-4000-8000-000000000099'::uuid]),'{}'::jsonb,'Unscheduled or unknown night has no planning status');
SELECT throws_ok($$SELECT public.rdd_planning_night_status(array_fill(gen_random_uuid(),ARRAY[41]))$$,'22023',null,'Status read is bounded');
SELECT * FROM finish();
ROLLBACK;
